-- ====================================================================
-- CivicSync Verification Tests: Scoring Formula & RLS Policies
-- Specification: RULES.pdf §1.8, SECURITY.pdf §10
-- ====================================================================

DO $$
DECLARE
    v_res RECORD;
BEGIN
    RAISE NOTICE '=== Running CivicSync Test Suite ===';

    -- Test 1: Worked Example 1 (Large pothole, main road, model 0.90 sure, 1 reporter)
    -- Expected: Score 90, Band Critical
    SELECT score, band INTO v_res
    FROM fn_calculate_priority_score('pothole'::hazard_class, 'large'::hazard_extent, 0.90, 0.90, 1);

    ASSERT v_res.score = 90, format('Test 1 Failed: Expected score 90, got %s', v_res.score);
    ASSERT v_res.band = 'critical', format('Test 1 Failed: Expected band critical, got %s', v_res.band);
    RAISE NOTICE 'Test 1 Passed: Case 1 correctly scored 90 (Critical)';

    -- Test 2: Worked Example 2 (Medium waterlogging, residential lane, 0.70 sure, 1 reporter)
    -- Expected: Score 53, Band Medium
    SELECT score, band INTO v_res
    FROM fn_calculate_priority_score('waterlogging'::hazard_class, 'medium'::hazard_extent, 0.70, 0.40, 1);

    ASSERT v_res.score = 53, format('Test 2 Failed: Expected score 53, got %s', v_res.score);
    ASSERT v_res.band = 'medium', format('Test 2 Failed: Expected band medium, got %s', v_res.band);
    RAISE NOTICE 'Test 2 Passed: Case 2 correctly scored 53 (Medium)';

    -- Test 3: Worked Example 3 (Same waterlogging, 4 distinct reporters)
    -- Expected: Score 62 (53 + 9 bonus), Band High
    SELECT score, band INTO v_res
    FROM fn_calculate_priority_score('waterlogging'::hazard_class, 'medium'::hazard_extent, 0.70, 0.40, 4);

    ASSERT v_res.score = 62, format('Test 3 Failed: Expected score 62, got %s', v_res.score);
    ASSERT v_res.band = 'high', format('Test 3 Failed: Expected band high, got %s', v_res.band);
    RAISE NOTICE 'Test 3 Passed: Case 3 with 4 reporters boosted to 62 (High)';

    -- Test 4: Worked Example 4 (Small broken road, near a school, 0.80 sure)
    -- Expected: Score 68, Band High
    SELECT score, band INTO v_res
    FROM fn_calculate_priority_score('broken_road'::hazard_class, 'small'::hazard_extent, 0.80, 1.00, 1);

    ASSERT v_res.score = 68, format('Test 4 Failed: Expected score 68, got %s', v_res.score);
    ASSERT v_res.band = 'high', format('Test 4 Failed: Expected band high, got %s', v_res.band);
    RAISE NOTICE 'Test 4 Passed: Case 4 correctly scored 68 (High)';

    -- Test 5: Location Context Proximity Check
    -- Point near Agra Hospital (78.0050, 27.1850) -> should yield 1.00
    DECLARE
        v_pt GEOGRAPHY;
        v_l REAL;
    BEGIN
        v_pt := ST_SetSRID(ST_MakePoint(78.0051, 27.1851), 4326)::geography;
        v_l := fn_get_location_context(v_pt);
        ASSERT v_l = 1.00, format('Test 5 Failed: Expected location context 1.00 near hospital, got %s', v_l);
        RAISE NOTICE 'Test 5 Passed: Proximity to hospital evaluates to L=1.00';
    END;

    RAISE NOTICE '=== All CivicSync SQL Tests Passed Successfully! ===';
END $$;

/// CivicSync Domain Constants & Rules
/// Specifications: RULES.pdf, PRD.pdf, TRD.pdf

enum HazardClass {
  pothole,
  openDrain,
  brokenRoad,
  waterlogging,
  other;

  String get dbValue {
    switch (this) {
      case HazardClass.pothole:
        return 'pothole';
      case HazardClass.openDrain:
        return 'open_drain';
      case HazardClass.brokenRoad:
        return 'broken_road';
      case HazardClass.waterlogging:
        return 'waterlogging';
      case HazardClass.other:
        return 'other';
    }
  }

  static HazardClass fromString(String value) {
    switch (value) {
      case 'open_drain':
        return HazardClass.openDrain;
      case 'pothole':
        return HazardClass.pothole;
      case 'broken_road':
        return HazardClass.brokenRoad;
      case 'waterlogging':
        return HazardClass.waterlogging;
      default:
        return HazardClass.other;
    }
  }

  double get classWeight {
    switch (this) {
      case HazardClass.openDrain:
        return 1.00;
      case HazardClass.pothole:
        return 0.80;
      case HazardClass.brokenRoad:
        return 0.60;
      case HazardClass.waterlogging:
        return 0.50;
      case HazardClass.other:
        return 0.40;
    }
  }
}

enum HazardExtent {
  small,
  medium,
  large,
  notSure;

  String get dbValue {
    switch (this) {
      case HazardExtent.small:
        return 'small';
      case HazardExtent.medium:
        return 'medium';
      case HazardExtent.large:
        return 'large';
      case HazardExtent.notSure:
        return 'not_sure';
    }
  }

  double get extentFactor {
    switch (this) {
      case HazardExtent.large:
        return 1.00;
      case HazardExtent.medium:
        return 0.60;
      case HazardExtent.small:
        return 0.30;
      case HazardExtent.notSure:
        return 0.50;
    }
  }
}

enum PlainStatus {
  received,
  checked,
  crewAssigned,
  fixed,
  rejected;

  String get displayNameEn {
    switch (this) {
      case PlainStatus.received:
        return 'Received';
      case PlainStatus.checked:
        return 'Checked';
      case PlainStatus.crewAssigned:
        return 'Crew assigned';
      case PlainStatus.fixed:
        return 'Fixed';
      case PlainStatus.rejected:
        return 'Not actionable';
    }
  }

  String get displayNameHi {
    switch (this) {
      case PlainStatus.received:
        return 'प्राप्त हुई';
      case PlainStatus.checked:
        return 'जाँच की गई';
      case PlainStatus.crewAssigned:
        return 'दल नियुक्त';
      case PlainStatus.fixed:
        return 'सुधार किया गया';
      case PlainStatus.rejected:
        return 'अमान्य';
    }
  }
}

class AppConstants {
  // Pilot Cities
  static const List<String> pilotCities = ['Agra', 'Jodhpur'];

  // Scoring Weights (RULES.pdf §1.1)
  static const double wClass = 0.30;
  static const double wExtent = 0.25;
  static const double wConf = 0.15;
  static const double wLocation = 0.30;
  static const double defaultLocationContext = 0.50; // Unknown on-device

  // Performance Targets (TRD.pdf §2)
  static const int targetInferenceMs = 150;
  static const int targetSubmissionSeconds = 3;
  static const int maxPhotoEdge = 1280;
  static const int maxPhotoKb = 300;
  static const int maxNoteChars = 200;

  // Thresholds (RULES.pdf §2, §6)
  static const double gpsGoodMaxMeters = 30.0;
  static const double gpsWeakMaxMeters = 100.0;
  static const double duplicateAutoMergeRadiusMeters = 25.0;
  static const double duplicateCandidateRadiusMeters = 50.0;

  // Preliminary Severity Calculator (RULES.pdf §1.5)
  static int computePreliminarySeverity({
    required HazardClass hazardClass,
    required HazardExtent extent,
    required double confidence,
  }) {
    final c = hazardClass.classWeight;
    final e = extent.extentFactor;
    final k = confidence.clamp(0.0, 1.0);
    final l = defaultLocationContext;

    final rawScore = 100.0 * (wClass * c + wExtent * e + wConf * k + wLocation * l);
    return rawScore.round().clamp(0, 100);
  }
}

